<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useActivityStore, type ActivityKind } from '../../stores/activity'
import { useSystemStore, useTradeStore } from '../../stores'
import { date } from '../../format'
const feed=useActivityStore();const system=useSystemStore();const trades=useTradeStore();const filter=ref<ActivityKind|'ALL'>('ALL');const top=ref(0);const scroll=ref<HTMLElement>()
const rowHeight=126;const visibleCount=9
const filtered=computed(()=>filter.value==='ALL'?feed.items:feed.items.filter(i=>i.kind===filter.value));const start=computed(()=>Math.max(0,Math.floor(top.value/rowHeight)-2));const visible=computed(()=>filtered.value.slice(start.value,start.value+visibleCount))
watch(filter,()=>{top.value=0;if(scroll.value)scroll.value.scrollTop=0})
function inspect(id:string|undefined){if(id)trades.selected=[...trades.open,...trades.closed].find(t=>t.id===id) ?? null}
</script>
<template><section class="card trade-feed" data-testid="trade-feed"><div class="panel-heading"><div><span class="eyebrow">EVENT STREAM · {{ system.connection }}</span><h2>Trade feed</h2></div><select v-model="filter" aria-label="Filtrar actividad"><option value="ALL">Todo</option><option v-for="kind in ['MARKET','SIGNAL','KRONOS','TRADE_OPEN','TRADE_UPDATE','TRADE_CLOSE','NO_TRADE','COST_REJECTION','PAPER','RISK','SOL','SYSTEM','ERROR']" :key="kind" :value="kind">{{ kind }}</option></select></div><div class="feed-counts"><span>{{ feed.items.filter(i=>i.kind==='KRONOS').length }} Kronos</span><span>{{ feed.items.filter(i=>i.kind==='SIGNAL').length }} señales</span><span>{{ feed.items.filter(i=>i.kind==='NO_TRADE'||i.kind==='COST_REJECTION').length }} rechazadas</span><span>{{ feed.items.filter(i=>i.kind==='TRADE_CLOSE').length }} cierres</span></div><p class="feed-note">{{ feed.items.length }} / {{ feed.limit }} eventos recientes · sesión de interfaz. SNAPSHOT = estado recuperado, no historial completo. {{ system.connection!=='CONNECTED'?'STALE · sin conexión':'' }}</p><div ref="scroll" class="feed-scroll" tabindex="0" aria-label="Actividad reciente con scroll" @scroll="top=($event.target as HTMLElement).scrollTop"><div v-if="filtered.length" class="feed-virtual" :style="{height:`${filtered.length*rowHeight}px`}"><ol :style="{transform:`translateY(${start*rowHeight}px)`}"><li v-for="item in visible" :key="item.id" class="feed-row" :data-kind="item.kind"><div class="feed-marker">{{ item.kind==='KRONOS'?'K':item.kind==='SOL'?'S':item.kind.startsWith('TRADE')?'↗':'·' }}</div><div class="feed-content"><div class="feed-meta"><b>{{ item.kind }}</b><time :datetime="item.at">{{ date(item.at) }}</time><span v-if="item.snapshot">SNAPSHOT</span></div><strong>{{ item.title }}</strong><p :title="item.detail">{{ item.detail }}</p><div class="feed-origin"><span>{{ item.origin }}</span><button v-if="item.tradeId" class="text-button" @click="inspect(item.tradeId)">Ver operación</button></div></div></li></ol></div><div v-else class="feed-empty"><b>Sin eventos {{ filter==='ALL'?'':filter }}</b><p>Esperando evidencia del hub. No se inventan señales ni operaciones.</p></div></div></section></template>
